{"template_html": "<div class="clock">
    <div class="inner-clock">
        [HH:mm:ss]
    </div>
    <p class="label">[label]</p>
</div>", "template_style": ".clock {
    background: #a6b1f2;
    color: #161616;
    width: 190px;
    height: 90px;
    border-radius: 15px;
    text-align: center;
    margin: 5px;
}

.inner-clock {
    position: relative;
    top: 20px;
    font-size: 24px;
}

.label {
    position: relative;
    font-size: 18px;
    top: 26px;
}", "widgetDesignWidth": 200, "widgetDesignHeight": 100, "worldClocks": "[{"clockTimezone":"Europe/Rome","clockLabel":"Rome","clockHighlight":0}]", "numCols": 1, "numRows": 1}

